{"command":"cd git-trim
cat <<'EOF' > src/main.rs
use std::collections::{HashMap, HashSet};
use std::process::Command;
use std::io::{self, Write};

#[derive(Debug, Clone)]
struct RefInfo {
    full_ref: String,
    objectname: String,
    upstream: Option<String>,
    upstream_remote: Option<String>,
}

fn git(args: &[&str]) -> String {
    let output = Command::new("git")
        .args(args)
        .output()
        .expect("Failed to execute git");
    String::from_utf8_lossy(&output.stdout).trim().to_string()
}

fn git_lines(args: &[&str]) -> Vec<String> {
    let out = git(args);
    if out.is_empty() {
        vec![]
    } else {
        out.lines().map(|s| s.to_string()).collect()
    }
}

fn is_merged(rev: &str, base: &str) -> bool {
    let output = Command::new("git")
        .args(&["merge-base", "--is-ancestor", rev, base])
        .status()
        .expect("Failed to execute git merge-base");
    output.success()
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.iter().any(|arg| arg == "--help" || arg == "-h") {
        print_help();
        return;
    }
    if args.iter().any(|arg| arg == "--version" || arg == "-V") {
        println!("git-trim 0.4.4");
        return;
    }

    let mut dry_run = false;
    let mut no_update = false;
    let mut no_confirm = false;
    let mut bases_arg: Option<String> = None;
    let mut delete_arg: Option<String> = None;
    let mut protected_arg: Option<String> = None;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--dry-run" => dry_run = true,
            "--no-update" => no_update = true,
            "--no-confirm" => no_confirm = true,
            "-b" | "--bases" => {
                i += 1;
                if i < args.len() { bases_arg = Some(args[i].clone()); }
            }
            "-d" | "--delete" => {
                i += 1;
                if i < args.len() { delete_arg = Some(args[i].clone()); }
            }
            "-p" | "--protected" => {
                i += 1;
                if i < args.len() { protected_arg = Some(args[i].clone()); }
            }
            _ => {}
        }
        i += 1;
    }

    // Default delete: merged:origin
    let delete_str = delete_arg.unwrap_or_else(|| "merged:origin".to_string());
    let mut delete_ranges = HashSet::new();
    for part in delete_str.split(',') {
        delete_ranges.insert(part.to_string());
    }

    if !no_update {
        // Fetching origin ... actually, we should find all remotes
        let remotes = git_lines(&["remote"]);
        for remote in remotes {
            println!("Fetching {}", remote);
            Command::new("git").args(&["fetch", &remote, "--prune"]).status().ok();
        }
        println!();
    }

    // Get all refs
    let lines = git_lines(&["for-each-ref", "--format=%(refname) %(objectname) %(upstream) %(upstream:remotename)", "refs/heads/", "refs/remotes/"]);
    let mut refs = HashMap::new();
    for line in lines {
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() >= 2 {
            refs.insert(parts[0].to_string(), RefInfo {
                full_ref: parts[0].to_string(),
                objectname: parts[1].to_string(),
                upstream: parts.get(2).filter(|s| !s.is_empty()).map(|s| s.to_string()),
                upstream_remote: parts.get(3).filter(|s| !s.is_empty()).map(|s| s.to_string()),
            });
        }
    }

    // Determine bases
    let mut base_upstreams = HashSet::new();
    let mut base_names = HashSet::new();

    if let Some(bases) = bases_arg {
        for name in bases.split(',') {
            let full_ref = if refs.contains_key(&format!("refs/heads/{}", name)) {
                format!("refs/heads/{}", name)
            } else {
                name.to_string()
            };
            base_names.insert(full_ref.clone());
            if let Some(info) = refs.get(&full_ref) {
                if let Some(ref u) = info.upstream {
                    base_upstreams.insert(u.clone());
                }
            }
        }
    } else {
        // Default bases: branches tracking refs/remotes/*/HEAD
        let head_refs = git_lines(&["for-each-ref", "--format=%(refname) %(symref)", "refs/remotes/*/HEAD"]);
        let mut head_targets = HashSet::new();
        for line in head_refs {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 2 {
                head_targets.insert(parts[1].to_string());
            }
        }
        for (full_ref, info) in &refs {
            if full_ref.starts_with("refs/heads/") {
                if let Some(ref u) = info.upstream {
                    if head_targets.contains(u) {
                        base_names.insert(full_ref.clone());
                        base_upstreams.insert(u.clone());
                    }
                }
            }
        }
    }

    // Analysis
    // ...
    println!("Branches that will remain:");
    // ...
}

fn print_help() {
    // ...
}
EOF
