fn git(args: &[&str]) -> String {
    let output = Command::new("git").args(args).output().expect("Failed to execute git");
    String::from_utf8_lossy(&output.stdout).trim().to_string()
}

fn git_lines(args: &[&str]) -> Vec<String> {
    let out = git(args);
    if out.is_empty() { vec![] } else { out.lines().map(|s| s.to_string()).collect() }
}

fn is_merged(rev: &str, bases: &HashSet<String>) -> bool {
    for base in bases {
        if Command::new("git").args(&["merge-base", "--is-ancestor", rev, base]).status().expect("Failed to execute git merge-base").success() {
            return true;
        }
    }
    false
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.iter().any(|arg| arg == "--help" || arg == "-h") { print_help(); return; }
    if args.iter().any(|arg| arg == "--version" || arg == "-V") { println!("git-trim 0.4.4"); return; }

    let (mut dry_run, mut no_update, mut no_detach) = (false, false, false);
    let (mut bases_arg, mut delete_arg) = (None, None);

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--dry-run" => dry_run = true,
            "--no-update" => no_update = true,
            "--no-detach" => no_detach = true,
            "-b" | "--bases" => { i += 1; if i < args.len() { bases_arg = Some(args[i].clone()); } }
            "-d" | "--delete" => { i += 1; if i < args.len() { delete_arg = Some(args[i].clone()); } }
            _ => {}
        }
        i += 1;
    }

    let delete_str = delete_arg.unwrap_or_else(|| "merged:origin".to_string());
    let (mut del_merged_local, mut del_stray, mut del_local) = (false, false, false);
    let (mut del_merged_remotes, mut del_diverged_remotes, mut del_remote_remotes) = (HashSet::new(), HashSet::new(), HashSet::new());
    for r in delete_str.split(',') {
        if r == "merged-local" { del_merged_local = true; }
        else if r == "stray" { del_stray = true; }
        else if r == "local" { del_local = true; }
        else if r.starts_with("merged-remote:") { del_merged_remotes.insert(r[14..].to_string()); }
        else if r.starts_with("diverged:") { del_diverged_remotes.insert(r[9..].to_string()); }
        else if r.starts_with("remote:") { del_remote_remotes.insert(r[7..].to_string()); }
        else if r.starts_with("merged:") { let remote = &r[7..]; del_merged_local = true; del_merged_remotes.insert(remote.to_string()); }
    }

    if !no_update {
        let remotes = git_lines(&["remote"]);
        for remote in remotes { println!("Fetching {}", remote); Command::new("git").args(&["fetch", &remote, "--prune"]).status().ok(); }
        println!();
    }

    let lines = git_lines(&["for-each-ref", "--format=%(refname) %(objectname) %(upstream) %(upstream:remotename)", "refs/heads/", "refs/remotes/"]);
    let mut refs = HashMap::new();
    for line in lines {
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() >= 2 {
            refs.insert(parts[0].to_string(), RefInfo {
                full_ref: parts[0].to_string(),
                short_name: if parts[0].starts_with("refs/heads/") { parts[0][11..].to_string() } else { parts[0][13..].to_string() },
                objectname: parts[1].to_string(),
                upstream: parts.get(2).filter(|s| !s.is_empty()).map(|s| s.to_string()),
                upstream_remote: parts.get(3).filter(|s| !s.is_empty()).map(|s| s.to_string()),
            });
        }
    }

    let mut base_upstreams = HashSet::new();
    let mut base_names = HashSet::new();
    if let Some(bases) = bases_arg {
        for name in bases.split(',') {
            let full_ref = if refs.contains_key(&format!("refs/heads/{}", name)) { format!("refs/heads/{}", name) } else { name.to_string() };
            base_names.insert(full_ref.clone());
            if let Some(info) = refs.get(&full_ref) { if let Some(ref u) = info.upstream { base_upstreams.insert(u.clone()); } }
        }
    } else {
        let head_refs = git_lines(&["for-each-ref", "--format=%(refname) %(symref)", "refs/remotes/*/HEAD"]);
        let mut head_targets = HashSet::new();
        for line in head_refs {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 2 { head_targets.insert(parts[1].to_string()); }
        }
        for (full_ref, info) in &refs {
            if full_ref.starts_with("refs/heads/") {
                if let Some(ref u) = info.upstream {
                    if head_targets.contains(u) { base_names.insert(full_ref.clone()); base_upstreams.insert(u.clone()); }
                }
            }
        }
    }

    let current_branch = git(&["rev-parse", "--symbolic-full-name", "HEAD"]);
    let mut to_delete_local = Vec::new();
    let mut to_delete_remote = Vec::<(String, String, String)>::new();
    let (mut remain_local, mut remain_remote) = (Vec::new(), Vec::new());
    let (mut skipped_2, mut skipped_3) = (false, false);

    for (full_ref, info) in &refs {
        if !full_ref.starts_with("refs/heads/") { continue; }
        let merged_l = is_merged(&info.objectname, &base_upstreams);
        let (mut reason, mut deleted, mut dtype) = (None, false, "");
        if base_names.contains(full_ref) { reason = Some("[base]"); }
        else if let Some(ref u) = info.upstream {
            if let Some(u_info) = refs.get(u) {
                let merged_u = is_merged(&u_info.objectname, &base_upstreams);
                let remote = info.upstream_remote.as_ref().unwrap();
                if merged_l && merged_u {
                    if del_merged_local { deleted = true; dtype = "Delete merged local branches:"; } else { reason = Some("[merged, but: delete range `merged-local` was not given]"); }
                    if del_merged_remotes.contains(remote) || del_merged_remotes.contains("*") { to_delete_remote.push((remote.clone(), u.clone(), "Delete merged remote refs:".to_string())); }
                } else if merged_l && !merged_u {
                    if del_diverged_remotes.contains(remote) || del_diverged_remotes.contains("*") { deleted = true; dtype = "Delete merged local branches:"; to_delete_remote.push((remote.clone(), u.clone(), "Delete diverged remote refs:".to_string())); }
                    else { reason = Some(Box::leak(format!("[diverged with {}, but: delete range `diverged:{}` was not given]", u, remote).into_boxed_str())); }
                } else if !merged_l && merged_u {
                    if del_stray { deleted = true; dtype = "Delete stray local branches:"; } else { reason = Some("[stray, but: delete range `stray` was not given]"); }
                    if del_merged_remotes.contains(remote) || del_merged_remotes.contains("*") { to_delete_remote.push((remote.clone(), u.clone(), "Delete merged remote refs:".to_string())); }
                }
            } else { if del_stray { deleted = true; dtype = "Delete stray local branches:"; } else { reason = Some("[stray, but: delete range `stray` was not given]"); } }
        } else if merged_l { if del_local { deleted = true; dtype = "Delete merged local branches:"; } else { reason = Some("*2"); skipped_2 = true; } }
        else { reason = Some("*2"); skipped_2 = true; }
        if deleted { to_delete_local.push((info.clone(), dtype)); } else { remain_local.push((info.short_name.clone(), reason)); }
    }

    let tracked_upstreams: HashSet<_> = refs.values().filter_map(|i| i.upstream.as_ref()).collect();
    for (full_ref, info) in &refs {
        if !full_ref.starts_with("refs/remotes/") || full_ref.ends_with("/HEAD") { continue; }
        let merged_u = is_merged(&info.objectname, &base_upstreams);
        let mut is_base = false;
        for bu in &base_upstreams { if bu == full_ref { is_base = true; break; } }
        let remote = full_ref.split('/').nth(2).unwrap();
        let mut deleted = to_delete_remote.iter().any(|(_, r, _)| r == full_ref);

        if is_base { remain_remote.push((info.short_name.clone(), Some("[base]"))); }
        else if merged_u && !tracked_upstreams.contains(full_ref) {
            if del_remote_remotes.contains(remote) || del_remote_remotes.contains("*") {
                if !deleted { to_delete_remote.push((remote.to_string(), full_ref.clone(), "Delete merged remote refs:".to_string())); deleted = true; }
            } else { remain_remote.push((info.short_name.clone(), Some("*3"))); skipped_3 = true; }
        }

        if !deleted && !is_base {
            let mut reason = None;
            if merged_u {
                if tracked_upstreams.contains(full_ref) {
                    if !del_merged_remotes.contains(remote) && !del_merged_remotes.contains("*") {
                        reason = Some(Box::leak(format!("[merged, but: delete range `merged-remote:{}` was not given]", remote).into_boxed_str()) as &str);
                    }
                }
            }
            remain_remote.push((info.short_name.clone(), reason));
        }
    }

    remain_local.sort_by(|a, b| a.0.cmp(&b.0));
    remain_remote.sort_by(|a, b| a.0.cmp(&b.0));
    println!("Branches that will remain:\n  local branches:");
    for (n, r) in remain_local { if let Some(re) = r { println!("    {} {}", n, re); } else { println!("    {}", n); } }
    println!("  remote references:");
    let mut seen_remotes = HashSet::new();
    for (n, r) in remain_remote { if seen_remotes.insert(n.clone()) { if let Some(re) = r { println!("    {} {}", n, re); } else { println!("    {}", n); } } }
    if skipped_2 || skipped_3 {
        println!("  Some branches are skipped. Consider following to scan them:");
        if skipped_2 { println!("    *2: Set an upstream to make it a tracking branch or add `--delete 'local'` flag."); }
        if skipped_3 { println!("    *3: Make it upstream of a tracking branch or add `--delete 'remote:origin'` flag."); }
    }

    let type_order = ["Delete merged local branches:", "Delete merged remote refs:", "Delete diverged remote refs:", "Delete stray local branches:"];
    for &t in &type_order {
        let mut first = true;
        for (info, dtype) in &to_delete_local { if *dtype == t { if first { println!("\n{}", t); first = false; } println!("  - {}", info.short_name); } }
        for (remote, rref, dtype) in &to_delete_remote { if dtype == t { if first { println!("\n{}", t); first = false; } println!("  - {}, refs/heads/{}", remote, rref.replace(&format!("refs/remotes/{}/", remote), "")); } }
    }

    let mut remote_to_refs = HashMap::new();
    for (remote, rref, _) in &to_delete_remote { remote_to_refs.entry(remote).or_insert(vec![]).push(rref); }
    let mut sorted_remotes: Vec<_> = remote_to_refs.keys().collect();
    sorted_remotes.sort();
    for remote in sorted_remotes {
        let url = git(&["remote", "get-url", remote]);
        println!("To {}", url);
        for rref in remote_to_refs.get(remote).unwrap() {
            let short = rref.replace(&format!("refs/remotes/{}/", remote), "");
            if !dry_run { Command::new("git").args(&["push", remote, "--delete", &short]).status().ok(); }
            println!(" - [deleted]         {}", short);
        }
    }

    for (info, _) in to_delete_local {
        if info.full_ref == current_branch {
            if no_detach { println!("Skip deleting current branch {}", info.short_name); continue; }
            if dry_run { println!("Note: switching to 'refs/heads/{}' (dry run)\nYou are in 'detached HEAD' state... (dry run)\nHEAD is now at {} (dry run)", info.short_name, info.objectname); }
            else { Command::new("git").args(&["checkout", "--detach"]).status().ok(); }
        }
        if dry_run { println!("Delete branch {} (dry run).", info.short_name); }
        else { let out = git(&["branch", "-d", &info.short_name]); println!("{}", out); }
    }
